import { cache } from 'react'

// Deduped per-request so each dashboard section can await its own slice
// independently (inside its own Suspense boundary) without triggering
// multiple network calls.
export const getDashboardData = cache(async () => {
  const res = await fetch('https://api.example.com/dashboard')
  return res.json()
})

