import { getDashboardData } from './data'

export async function CardStats() {
  const data = await getDashboardData()

  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>${data.totalRevenue.toLocaleString()}</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p>{data.totalInvoices}</p>
      </div>
    </div>
  )
}

export function CardStatsSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card">
        <h2>Total Revenue</h2>
        <p className="skeleton">&nbsp;</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p className="skeleton">&nbsp;</p>
      </div>
    </div>
  )
}

